import { useEffect, useState } from 'react';

export function {{component_name}}() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [remember, setRemember] = useState({{remember_me}});
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if ({{remember_me}}) {
      const saved = localStorage.getItem('bragi.login.email');
      if (saved) setEmail(saved);
    }
  }, []);

  async function handleSubmit(e) {
    e.preventDefault();
    setLoading(true);
    setError(null);
    try {
      const resp = await fetch('{{submit_endpoint}}', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
      });
      if (!resp.ok) throw new Error('登入失敗');
      if (remember && {{remember_me}}) {
        localStorage.setItem('bragi.login.email', email);
      } else {
        localStorage.removeItem('bragi.login.email');
      }
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} className="max-w-sm mx-auto p-6 space-y-4">
      <div>
        <label className="block text-sm mb-1">{{username_label}}</label>
        <input
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
          className="w-full border rounded px-3 py-2"
        />
      </div>
      <div>
        <label className="block text-sm mb-1">密碼</label>
        <input
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
          className="w-full border rounded px-3 py-2"
        />
      </div>
      {{{remember_me}} && (
        <label className="flex items-center gap-2 text-sm">
          <input
            type="checkbox"
            checked={remember}
            onChange={(e) => setRemember(e.target.checked)}
          />
          記住我
        </label>
      )}
      {error && <p className="text-red-600 text-sm">{error}</p>}
      <button
        type="submit"
        disabled={loading}
        className="w-full bg-{{primary_color}} text-white py-2 rounded disabled:opacity-50"
      >
        {loading ? '登入中⋯' : '登入'}
      </button>
    </form>
  );
}
